@push('styles')<link href="https://cdn.jsdelivr.net/npm/fullcalendar@6.1.15/index.global.min.css" rel="stylesheet"><style>.detail-hero{display:grid;grid-template-columns:1.2fr 1fr;gap:24px;align-items:center;background:linear-gradient(120deg,var(--surface),var(--blue-soft))}.detail-hero h2{font-size:24px;margin:8px 0}.detail-hero-main p{color:var(--muted);max-width:680px}.detail-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.detail-stats>div{background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:16px 8px;text-align:center}.detail-stats strong{display:block;font-size:27px}.detail-stats span{font-size:10px;color:var(--muted)}.text-green{color:#16A34A}.text-amber{color:#D97706}.borrow-panel{display:flex;justify-content:space-between;align-items:center;gap:20px}.borrow-panel p{margin:4px 0 0;font-size:11px}.detail-columns{display:grid;grid-template-columns:1fr 1fr;gap:16px}.condition-list{display:grid;gap:10px}.condition-list>div{display:grid;grid-template-columns:1fr auto auto;gap:10px;align-items:center;padding:9px 0;border-bottom:1px solid var(--line);font-size:11px}.calendar-legend{display:flex;gap:16px;flex-wrap:wrap;margin-bottom:14px;font-size:11px;color:var(--muted)}.legend-dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:5px}.legend-dot.loan{background:#2563EB}.legend-dot.maintenance{background:#D97706}.legend-dot.today{background:#16A34A}#itemAvailabilityCalendar{min-height:430px}.fc .fc-toolbar-title{font-size:17px}.fc .fc-button{background:var(--navy);border-color:var(--navy);font-size:11px}.fc .fc-button-primary:not(:disabled).fc-button-active{background:var(--teal);border-color:var(--teal);color:#103B52}@media(max-width:800px){.detail-hero,.detail-columns{grid-template-columns:1fr}.borrow-panel{align-items:flex-start;flex-direction:column}.borrow-panel form{width:100%}}</style>@endpush
@push('scripts')<script src="https://cdn.jsdelivr.net/npm/fullcalendar@6.1.15/index.global.min.js"></script><script>
document.addEventListener('DOMContentLoaded',()=>{const el=document.getElementById('itemAvailabilityCalendar');if(!el||!window.FullCalendar)return;new FullCalendar.Calendar(el,{initialView:'dayGridMonth',locale:'id',height:'auto',fixedWeekCount:false,dayMaxEvents:3,headerToolbar:{left:'prev,next today',center:'title',right:'dayGridMonth,timeGridWeek,listMonth'},buttonText:{today:'Hari ini',month:'Bulan',week:'Minggu',list:'Agenda'},events:@json($availabilityEvents),eventDisplay:'block'}).render();});
document.querySelectorAll('[data-quick-add]').forEach(form=>form.addEventListener('submit',async e=>{e.preventDefault();const b=form.querySelector('button'),old=b.innerHTML;b.disabled=true;try{const r=await fetch(form.action,{method:'POST',body:new FormData(form),headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content}});const j=await r.json();if(!r.ok)throw new Error(j.message||'Tidak dapat menambahkan barang');window.updateFloatingCart?.(j.cart_count);const t=document.createElement('div');t.className='alert';t.textContent=j.message+` Total keranjang: ${j.cart_count} unit.`;document.getElementById('inventoryToast').append(t);setTimeout(()=>t.remove(),4000);}catch(x){alert(x.message)}finally{b.disabled=false;b.innerHTML=old;}}));
</script>@endpush
